#!/usr/bin/env python3
"""Pack props/ai-audio/*.mp3 into props/audio-data.js (window.VN_AUDIO_ASSETS).

BGM stems equal background ids (plus "title") so audio.js's sampled-bed
layer picks them up via VN_AUDIO.scene(bgId); sfx_* files keep their names.
Files are embedded exactly as delivered — no trimming.
"""
import base64
from pathlib import Path

HERE = Path(__file__).resolve().parent
KEY_REMAP = {}  # stems are already bg ids / sfx names

out = [
    "// Generated by ai-audio/make-audio-data.py — do not edit.",
    "// Sampled beds keyed by background id; audio.js prefers these over synth.",
    "window.VN_AUDIO_ASSETS = {",
]
total = 0
packed = 0
for f in sorted(HERE.glob("*.mp3")):
    key = KEY_REMAP.get(f.stem, f.stem)
    data = base64.b64encode(f.read_bytes()).decode()
    total += len(data)
    packed += 1
    out.append(f"  {key}: 'data:audio/mpeg;base64,{data}',")
out.append("};")
(HERE.parent / "audio-data.js").write_text("\n".join(out), encoding="utf-8")
print(f"audio-data.js written: {packed} tracks, base64 payload ~{total // 1024} KB")
